import "./App.css";
import { useEffect, useRef, useState } from "react";

const HUD_HINT =
  "WASD move · SHIFT sprint · SPACE jump · drag mouse = camera · scroll = zoom · P pause · M mute";

function HudOverlay({ hud }) {
  if (!hud?.visible) return null;

  return (
    <div className="react-hud">
      <div className="react-hud-top">
        <div className="react-xp-wrap">
          <div className="react-xp-bar" style={{ width: `${hud.xpPct}%` }} />
        </div>
        <div className="react-level-badge">LV {hud.level}</div>
        <div className="react-timer">{hud.time}</div>
        <div className="react-stats">
          <div>☠️ {hud.kills}</div>
          <div>💰 {hud.gold}</div>
        </div>
      </div>

      <div className="react-weapon-tray">
        {hud.weapons.map((weapon) => (
          <div className="react-weapon-slot" key={weapon.id}>
            <span>
              {weapon.emoji} {weapon.name}
            </span>
            <span className="react-weapon-pips">
              {"●".repeat(weapon.level)}
              {"○".repeat(weapon.max - weapon.level)}
            </span>
          </div>
        ))}
        {hud.passives.length > 0 && (
          <div className="react-passive-tray">
            {hud.passives.map((passive) => (
              <div className="react-passive-chip" key={passive.id} title={passive.name}>
                {passive.emoji}
                {passive.count > 1 ? `×${passive.count}` : ""}
              </div>
            ))}
          </div>
        )}
      </div>

      {hud.boss && (
        <div className="react-boss-wrap">
          <div className="react-boss-name">{hud.boss.name}</div>
          <div className="react-boss-outer">
            <div className="react-boss-fill" style={{ width: `${hud.boss.hpPct}%` }} />
          </div>
        </div>
      )}

      <div className="react-hp-wrap">
        <div className="react-hp-outer">
          <div className="react-hp-fill" style={{ width: `${(hud.hp / hud.maxHp) * 100}%` }} />
        </div>
        <div className="react-hp-text">
          {hud.hp}/{hud.maxHp}
        </div>
        <div className={`react-stam-outer${hud.winded ? " winded" : ""}`}>
          <div className="react-stam-fill" style={{ width: `${hud.staminaPct}%` }} />
        </div>
      </div>

      {hud.combo > 0 && <div className="react-combo">{hud.combo}x COMBO</div>}

      <div className="react-hint">{HUD_HINT}</div>
    </div>
  );
}

function ScreenOverlay({ hud, onCommand }) {
  if (!hud) return null;

  if (hud.state === "levelup" && hud.levelup) {
    return (
      <div className="react-screen levelup">
        <div className="react-screen-panel">
          <div className="react-levelup-title">{hud.levelup.title}</div>
          <div className="react-card-grid">
            {hud.levelup.cards.map((card, index) => (
              <button
                key={`${card.kind}-${card.id}-${index}`}
                className="react-upgrade-card"
                onClick={() => onCommand("pickLevelupCard", { index })}
              >
                <div className="react-upgrade-emoji">{card.emoji}</div>
                <div className="react-upgrade-name">{card.name}</div>
                <div className="react-upgrade-level">{card.levelLabel || "\u00A0"}</div>
                <div className="react-upgrade-desc">{card.desc}</div>
                <div className="react-upgrade-tag">{card.tag}</div>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (hud.overlayScreen === "menu") {
    return (
      <div className="react-screen">
        <div className="react-screen-panel">
          <div className="react-title">CUBE BASHER</div>
          <div className="react-subtitle">~ they're evil cubes. you have a duck. ~</div>
          <div className="react-menu-coins">🪙 {hud.menu.coins} coins</div>
          <div className="react-char-row">
            {hud.menu.characters.map((character) => (
              <button
                key={character.id}
                className={`react-char-card${character.selected ? " selected" : ""}`}
                onClick={() => onCommand("selectCharacter", { index: character.index })}
              >
                <div className="react-char-emoji">{character.emoji}</div>
                <div className="react-char-name">{character.name}</div>
                <div
                  className="react-char-desc"
                  dangerouslySetInnerHTML={{ __html: character.desc }}
                />
              </button>
            ))}
          </div>
          <div className="react-btn-row">
            <button className="react-big-btn" onClick={() => onCommand("startGame")}>
              BASH!
            </button>
            <button className="react-big-btn secondary" onClick={() => onCommand("openShop")}>
              UPGRADES
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (hud.overlayScreen === "pause") {
    return (
      <div className="react-screen">
        <div className="react-screen-panel narrow">
          <div className="react-end-title pause">PAUSED</div>
          <div className="react-end-stats">press P to resume</div>
          <div className="react-btn-row">
            <button className="react-big-btn" onClick={() => onCommand("resumePause")}>
              RESUME
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (hud.overlayScreen === "shop" && hud.shop) {
    return (
      <div className="react-screen shop">
        <div className="react-screen-panel">
          <div className="react-shop-title">UPGRADE LAB</div>
          <div className="react-shop-coins">🪙 {hud.shop.coins} coins</div>
          <div className="react-shop-grid">
            {hud.shop.items.map((item) => (
              <div className="react-shop-card" key={item.id}>
                <div className="react-upgrade-emoji small">{item.emoji}</div>
                <div className="react-upgrade-name shop">{item.name}</div>
                <div className="react-shop-desc">{item.desc}</div>
                <div className="react-shop-pips">
                  {"●".repeat(item.level)}
                  <span>{ "●".repeat(item.max - item.level) }</span>
                </div>
                <button
                  className="react-shop-buy"
                  disabled={!item.canBuy}
                  onClick={() => onCommand("buyMetaUpgrade", { id: item.id })}
                >
                  {item.maxed ? "MAXED" : `${item.cost} 🪙`}
                </button>
              </div>
            ))}
          </div>
          <div className="react-btn-row">
            <button className="react-big-btn" onClick={() => onCommand("closeShop")}>
              BACK
            </button>
          </div>
          <button
            className="react-reset-btn"
            onClick={() => {
              if (window.confirm("Reset ALL progress (coins + upgrades)?")) {
                onCommand("resetSave", { confirmed: true });
              }
            }}
          >
            reset all progress
          </button>
        </div>
      </div>
    );
  }

  if (hud.overlayScreen === "dead" || hud.overlayScreen === "win") {
    const dead = hud.overlayScreen === "dead";
    return (
      <div className="react-screen">
        <div className="react-screen-panel narrow">
          <div className={`react-end-title ${dead ? "dead" : "win"}`}>
            {dead ? "YOU GOT BASHED" : "YOU BASHED THE WORLD"}
          </div>
          <div
            className="react-end-stats"
            dangerouslySetInnerHTML={{ __html: hud.endStatsHtml || "" }}
          />
          <div className="react-btn-row">
            <button className="react-big-btn" onClick={() => onCommand("startGame")}>
              {dead ? "TRY AGAIN" : "ONE MORE RUN"}
            </button>
            <button className="react-big-btn secondary" onClick={() => onCommand("openShop")}>
              UPGRADES
            </button>
          </div>
        </div>
      </div>
    );
  }

  return null;
}

function App() {
  const iframeRef = useRef(null);
  const [hud, setHud] = useState(null);

  useEffect(() => {
    const handleMessage = (event) => {
      if (event.origin !== window.location.origin) return;
      if (event.data?.type !== "infinft:hud") return;
      setHud(event.data.payload);
    };

    window.addEventListener("message", handleMessage);
    return () => window.removeEventListener("message", handleMessage);
  }, []);

  const sendCommand = (action, payload = {}) => {
    const frame = iframeRef.current;
    if (!frame?.contentWindow) return;
    frame.contentWindow.postMessage(
      { type: "infinft:command", action, payload },
      window.location.origin
    );
  };

  return (
    <div className="app-shell">
      <aside className="app-sidebar">
        <p className="eyebrow">infiNFT Basher</p>
        <h1>Cube Basher</h1>
        <p className="intro">
          React now owns the app shell and primary game UI while the original
          Three.js gameplay still runs intact underneath.
        </p>

        <div className="panel">
          <h2>Current Migration Stage</h2>
          <p>
            React is now handling the frame, HUD, menus, level-up cards, and
            the Upgrade Lab. The gameplay, graphics, audio, save system, and
            combat loop are still preserved in the legacy runtime.
          </p>
        </div>

        <div className="panel">
          <h2>Why This Structure</h2>
          <p>
            The safest path is to migrate menus, HUD, and state boundaries into
            React first, then extract gameplay systems from the legacy file in
            smaller passes.
          </p>
        </div>

        <div className="panel">
          <h2>Next Steps</h2>
          <ul>
            <li>Extract gameplay systems from the single legacy runtime file.</li>
            <li>Extract save, audio, and game config into modules.</li>
            <li>Mount Three.js directly from a React game canvas component.</li>
          </ul>
        </div>

        <a className="launch-link" href="/legacy/index.html" target="_blank" rel="noreferrer">
          Open Legacy Runtime
        </a>
      </aside>

      <main className="app-main">
        <div className="game-frame-wrap">
          <HudOverlay hud={hud} />
          <ScreenOverlay hud={hud} onCommand={sendCommand} />
          <iframe
            ref={iframeRef}
            className="game-frame"
            src="/legacy/index.html"
            title="Cube Basher Legacy Runtime"
          />
        </div>
      </main>
    </div>
  );
}

export default App;
